const body = $json.body || $json;
const headers = $json.headers || {};
const lowerHeaders = {};
for (const [k, v] of Object.entries(headers)) {
  lowerHeaders[String(k).toLowerCase()] = v;
}

const verificationCode = body.verificationCode || null;
const eventType = body.type || body.eventType || body.objectType || null;

const paymentId =
  body.paymentId ||
  body.id ||
  body.objectId ||
  body.data?.paymentId ||
  body.data?.id ||
  body.payment?.id ||
  null;

const merchantId =
  body.merchantId ||
  body.mId ||
  body.merchant_id ||
  body.data?.merchantId ||
  body.payment?.merchantId ||
  null;

return [{
  json: {
    verificationCode,
    eventType,
    paymentId: paymentId ? String(paymentId) : null,
    merchantId: merchantId ? String(merchantId) : null,
    raw_body: body,
    raw_headers: lowerHeaders,
    mode: verificationCode ? 'verify' : (paymentId ? 'payment' : 'ignore')
  }
}];

function toIso(value) {
  if (!value) return null;
  const n = Number(value);
  if (Number.isFinite(n) && n > 1000000000) return new Date(n).toISOString();
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

const webhook = $('Code - Parse Clover Webhook').first().json;
const payment = $json;

const merchantIdExpected = String($env.CLOVER_MERCHANT_ID || '');
const merchantIdActual =
  String(payment.merchant?.id || payment.merchantId || webhook.merchantId || '');

const amountCents = Number(payment.amount ?? 0);
const tipCents = Number(payment.tipAmount ?? 0);
const taxCents = Number(payment.taxAmount ?? 0);

const amount = Number.isFinite(amountCents) ? amountCents / 100 : null;
const tipAmount = Number.isFinite(tipCents) ? tipCents / 100 : 0;
const taxAmount = Number.isFinite(taxCents) ? taxCents / 100 : 0;

const paymentTime =
  toIso(payment.createdTime) ||
  toIso(payment.clientCreatedTime) ||
  toIso(payment.modifiedTime) ||
  new Date().toISOString();

const orderId = String(payment.order?.id || payment.orderId || '');
const result = String(payment.result || payment.status || '').toUpperCase();
const tenderLabel = payment.tender?.label || payment.tender?.labelKey || payment.tender?.name || null;
const externalReferenceId = payment.externalReferenceId || payment.external_reference_id || null;

const merchantOk = !!merchantIdExpected && merchantIdActual === merchantIdExpected;
const amountOk = Number.isFinite(amount) && amount > 0;

return [{
  json: {
    merchant_ok: merchantOk,
    payment_id: String(payment.id || webhook.paymentId || ''),
    order_id: orderId || null,
    amount,
    amount_cents: amountCents,
    tip_amount: tipAmount,
    tax_amount: taxAmount,
    payment_time: paymentTime,
    result,
    tender_label: tenderLabel,
    external_reference_id: externalReferenceId,
    note: payment.note || null,
    raw_payment: payment,
    should_continue: merchantOk && amountOk
  }
}];

const payment = $('Code - Normalize Clover Payment').first().json;
const airtable = $json;
const records = airtable.records || [];
const windowMinutes = Number($env.CLOVER_MATCH_WINDOW_MINUTES || 15);
const paymentTs = new Date(payment.payment_time).getTime();

function toMs(value) {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.getTime();
}

const candidates = [];
for (const rec of records) {
  const f = rec.fields || {};
  const orderTs = toMs(f.order_date);
  const deltaMinutes = orderTs === null ? null : Math.abs(paymentTs - orderTs) / 60000;

  if (deltaMinutes !== null && deltaMinutes <= windowMinutes) {
    candidates.push({
      id: rec.id,
      fields: f,
      deltaMinutes
    });
  }
}

candidates.sort((a, b) => (a.deltaMinutes ?? 999999) - (b.deltaMinutes ?? 999999));

let matchStatus = 'not_found';
let confidence = null;
let chosen = null;
let note = '';

if (candidates.length === 1) {
  chosen = candidates[0];
  matchStatus = 'reconciled';
  confidence = 95;
  note = `Matched by amount and order_date within ${windowMinutes} minutes.`;
} else if (candidates.length > 1) {
  chosen = candidates[0];
  matchStatus = 'needs_review';
  confidence = 40;
  note = `Multiple pending Ecwid orders matched amount within ${windowMinutes} minutes. Closest candidate selected for review only; no payment_status update applied.`;
} else {
  note = `No pending Ecwid orders matched amount within ${windowMinutes} minutes.`;
}

return [{
  json: {
    match_status: matchStatus,
    confidence,
    note,
    candidate_count: candidates.length,
    chosen_record_id: chosen?.id || null,
    chosen_fields: chosen?.fields || null,
    candidates
  }
}];
